body:
It looks like this is a bit more common problem and it affects all generic methods. For example, this test method produces exactly the same error:

``` C#
[TestCase( 1, "2" )]
public void MyTest<T>( T x, T y )
{
    Assert.That( true );
}
```

In fact, `MethodInfo.MakeGenericMethod(...)` doesn't allow creating `SomeMethod(int x, string y)` from `SomeMethod <T>(T x, T y)`. The problem is that the method `NUnitTestCaseBuilder.GetTypeArgumentsForMethod(...)` doesn’t work correctly in all cases. In the example above, it returns `int[] { typeof(int) }` instead of indicating that types of arguments X and Y cannot be converted to each other.

In order to fix it we can do something like this:

``` diff
 .../Internal/Builders/NUnitTestCaseBuilder.cs      | 30 +++++++++-------------
 1 file changed, 12 insertions(+), 18 deletions(-)

diff --git a/src/NUnitFramework/framework/Internal/Builders/NUnitTestCaseBuilder.cs b/src/NUnitFramework/framework/Internal/Builders/NUnitTestCaseBuilder.cs
index 176e038..be88bac 100644
--- a/src/NUnitFramework/framework/Internal/Builders/NUnitTestCaseBuilder.cs
+++ b/src/NUnitFramework/framework/Internal/Builders/NUnitTestCaseBuilder.cs
@@ -202,8 +202,8 @@ namespace NUnit.Framework.Internal.Builders
             if (testMethod.Method.IsGenericMethodDefinition)
             {
                 Type[] typeArguments = GetTypeArgumentsForMethod(testMethod.Method, arglist);
-                foreach (object o in typeArguments)
-                    if (o == null)
+                foreach (Type o in typeArguments)
+                    if (o == null || o == typeof( TypeHelper.NonmatchingType ))
                     {
                         return MarkAsNotRunnable(testMethod, "Unable to determine type arguments for method");
                     }
@@ -220,27 +220,21 @@ namespace NUnit.Framework.Internal.Builders

         private static Type[] GetTypeArgumentsForMethod(MethodInfo method, object[] arglist)
         {
-            Type[] typeParameters = method.GetGenericArguments();
-            Type[] typeArguments = new Type[typeParameters.Length];
+            Type[] typeArguments = new Type[method.GetGenericArguments().Length];
             ParameterInfo[] parameters = method.GetParameters();

-            for (int typeIndex = 0; typeIndex < typeArguments.Length; typeIndex++)
+            for ( int argIndex = 0; argIndex < parameters.Length; argIndex++ )
             {
-                Type typeParameter = typeParameters[typeIndex];
+                var pi = parameters[argIndex];
+                var arg = arglist[argIndex];

-                for (int argIndex = 0; argIndex < parameters.Length; argIndex++)
+                if ( pi.ParameterType.IsGenericParameter )
                 {
-                    if (parameters[argIndex].ParameterType.Equals(typeParameter))
-                    {
-                        // If a null arg is provided, pass null as the Type
-                        // BestCommonType knows how to deal with this
-                        Type argType = arglist[argIndex] != null
-                            ? arglist[argIndex].GetType()
-                            : null;
-                        typeArguments[typeIndex] = TypeHelper.BestCommonType(
-                            typeArguments[typeIndex],
-                            argType);
-                    }
+                    // If a null arg is provided, pass null as the Type
+                    // BestCommonType knows how to deal with this
+                    var typeArgIndex = pi.ParameterType.GenericParameterPosition;
+                    var argType = arg != null ? arg.GetType() : null;
+                    typeArguments[typeArgIndex] = TypeHelper.BestCommonType( typeArguments[typeArgIndex], argType );
                 }
             }

 src/NUnitFramework/framework/Internal/TypeHelper.cs | 15 ++++++++++++++-
 1 file changed, 14 insertions(+), 1 deletion(-)

diff --git a/src/NUnitFramework/framework/Internal/TypeHelper.cs b/src/NUnitFramework/framework/Internal/TypeHelper.cs
index ea9e4a3..54eb2a2 100644
--- a/src/NUnitFramework/framework/Internal/TypeHelper.cs
+++ b/src/NUnitFramework/framework/Internal/TypeHelper.cs
@@ -36,6 +36,13 @@ namespace NUnit.Framework.Internal
     public class TypeHelper
     {
         /// <summary>
+        /// ...?
+        /// </summary>
+        public sealed class NonmatchingType
+        {
+        }
+
+        /// <summary>
         /// Gets the display name for a Type as used by NUnit.
         /// </summary>
         /// <param name="type">The Type for which a display name is needed.</param>
@@ -126,6 +133,9 @@ namespace NUnit.Framework.Internal
         /// <returns>Either type1 or type2, depending on which is more general.</returns>
         public static Type BestCommonType(Type type1, Type type2)
         {
+            if ( type1 == typeof( NonmatchingType ) ) return typeof( NonmatchingType );
+            if ( type2 == typeof( NonmatchingType ) ) return typeof( NonmatchingType );
+
             if (type1 == type2) return type1;
             if (type1 == null) return type2;
             if (type2 == null) return type1;
@@ -166,7 +176,10 @@ namespace NUnit.Framework.Internal
                 if (type2 == typeof(sbyte)) return type2;
             }

-            return type1;
+            if ( type1.IsAssignableFrom( type2 ) ) return type1;
+            if ( type2.IsAssignableFrom( type1 ) ) return type2;
+
+            return typeof( NonmatchingType );
         }

         /// <summary>
```
